TABLE_DDL = ("\nCREATE TABLE public.accounts (\n\tid VARCHAR(255) NOT NULL, \n\tcurrency VARCHAR(16) NOT NULL, \n\tledger_version BIGINT DEFAULT '0' NOT NULL, \n\tPRIMARY KEY (id)\n)\n\n", '\nCREATE TABLE public.agent_runs (\n\tid VARCHAR(255) NOT NULL, \n\tinput_hash VARCHAR(255) NOT NULL, \n\tconfig_version VARCHAR(255) NOT NULL, \n\tcheckpoint_id VARCHAR(255), \n\tstatus VARCHAR(255) NOT NULL, \n\theartbeat_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\toutput_id VARCHAR(255), \n\ttrace_id VARCHAR(255) NOT NULL, \n\tPRIMARY KEY (id)\n)\n\n', '\nCREATE TABLE public.audit_events (\n\tid VARCHAR(255) NOT NULL, \n\toccurred_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tactor_id VARCHAR(255) NOT NULL, \n\taction VARCHAR(255) NOT NULL, \n\treason_codes JSONB NOT NULL, \n\tentity_id VARCHAR(255) NOT NULL, \n\tentity_version INTEGER NOT NULL, \n\ttrace_id VARCHAR(255) NOT NULL, \n\tpolicy_version INTEGER, \n\toutcome VARCHAR(255), \n\ttransaction_id BIGINT DEFAULT txid_current() NOT NULL, \n\tPRIMARY KEY (id)\n)\n\n', '\nCREATE TABLE public.instruments (\n\tid VARCHAR(255) NOT NULL, \n\tmarket VARCHAR(255) NOT NULL, \n\tbroker_symbol VARCHAR(255) NOT NULL, \n\tasset_class VARCHAR(255) NOT NULL, \n\tcurrency VARCHAR(255) NOT NULL, \n\tversion INTEGER NOT NULL, \n\tsession_name VARCHAR(255) NOT NULL, \n\tquantity_step NUMERIC(38, 18), \n\tprice_tick NUMERIC(38, 18), \n\tPRIMARY KEY (id)\n)\n\n', '\nCREATE TABLE public.portfolio_snapshots (\n\tid VARCHAR(255) NOT NULL, \n\tcurrency VARCHAR(255) NOT NULL, \n\tequity NUMERIC(38, 18) NOT NULL, \n\tcash NUMERIC(38, 18) NOT NULL, \n\texposure NUMERIC(38, 18) NOT NULL, \n\tas_of TIMESTAMP WITH TIME ZONE NOT NULL, \n\tledger_version INTEGER NOT NULL, \n\tquality VARCHAR(255) NOT NULL, \n\treconciliation VARCHAR(255) NOT NULL, \n\tPRIMARY KEY (id)\n)\n\n', '\nCREATE TABLE public.evidence_bundles (\n\tid VARCHAR(255) NOT NULL, \n\tinstrument_id VARCHAR(255) NOT NULL, \n\tsources JSONB NOT NULL, \n\tavailable_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tconflicts JSONB NOT NULL, \n\tquality VARCHAR(255) NOT NULL, \n\tneutral BOOLEAN NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(instrument_id) REFERENCES public.instruments (id) ON DELETE RESTRICT\n)\n\n', '\nCREATE TABLE public.market_bars (\n\tid VARCHAR(255) NOT NULL, \n\tinstrument_id VARCHAR(255) NOT NULL, \n\tstart_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tend_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\topen NUMERIC(38, 18) NOT NULL, \n\thigh NUMERIC(38, 18) NOT NULL, \n\tlow NUMERIC(38, 18) NOT NULL, \n\tclose NUMERIC(38, 18) NOT NULL, \n\tvolume NUMERIC(38, 18) NOT NULL, \n\tevent_time TIMESTAMP WITH TIME ZONE NOT NULL, \n\treceived_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tavailable_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tquality VARCHAR(255) NOT NULL, \n\tinterval VARCHAR(255) NOT NULL, \n\tclosed BOOLEAN NOT NULL, \n\tversion INTEGER NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(instrument_id) REFERENCES public.instruments (id) ON DELETE RESTRICT\n)\n\n', '\nCREATE TABLE public.positions (\n\tid VARCHAR(255) NOT NULL, \n\tinstrument_id VARCHAR(255) NOT NULL, \n\tcurrency VARCHAR(255) NOT NULL, \n\tquantity NUMERIC(38, 18) NOT NULL, \n\taverage_price NUMERIC(38, 18), \n\trealized_pnl NUMERIC(38, 18) NOT NULL, \n\tledger_version INTEGER NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(instrument_id) REFERENCES public.instruments (id) ON DELETE RESTRICT\n)\n\n', '\nCREATE TABLE public.risk_policies (\n\tid VARCHAR(255) NOT NULL, \n\tversion INTEGER NOT NULL, \n\tcurrency VARCHAR(255) NOT NULL, \n\tmax_positions_per_instrument INTEGER NOT NULL, \n\tmax_positions_total INTEGER NOT NULL, \n\tmax_position_fraction NUMERIC(38, 18) NOT NULL, \n\tmax_daily_loss_fraction NUMERIC(38, 18) NOT NULL, \n\teffective_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tactor_id VARCHAR(255) NOT NULL, \n\taudit_event_id VARCHAR(255) NOT NULL, \n\tsimulation BOOLEAN NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_policy_version UNIQUE (version), \n\tFOREIGN KEY(audit_event_id) REFERENCES public.audit_events (id) ON DELETE RESTRICT\n)\n\n', '\nCREATE TABLE public.position_versions (\n\tposition_id VARCHAR(255) NOT NULL, \n\tledger_version INTEGER NOT NULL, \n\tinstrument_id VARCHAR(255) NOT NULL, \n\tcurrency VARCHAR(255) NOT NULL, \n\tquantity NUMERIC(38, 18) NOT NULL, \n\taverage_price NUMERIC(38, 18), \n\trealized_pnl NUMERIC(38, 18) NOT NULL, \n\tPRIMARY KEY (position_id, ledger_version), \n\tFOREIGN KEY(position_id) REFERENCES public.positions (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(instrument_id) REFERENCES public.instruments (id) ON DELETE RESTRICT\n)\n\n', '\nCREATE TABLE public.market_states (\n\tid VARCHAR(255) NOT NULL, \n\tinstrument_id VARCHAR(255) NOT NULL, \n\tmarket VARCHAR(255) NOT NULL, \n\tbar_id VARCHAR(255) NOT NULL, \n\tevidence_id VARCHAR(255) NOT NULL, \n\tportfolio_id VARCHAR(255) NOT NULL, \n\tposition_id VARCHAR(255) NOT NULL, \n\tfeatures JSONB NOT NULL, \n\tspread NUMERIC(38, 18) NOT NULL, \n\tevent_time TIMESTAMP WITH TIME ZONE NOT NULL, \n\treceived_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tavailable_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tas_of TIMESTAMP WITH TIME ZONE NOT NULL, \n\tquality VARCHAR(255) NOT NULL, \n\ttrace_id VARCHAR(255) NOT NULL, \n\tposition_ledger_version INTEGER NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(instrument_id) REFERENCES public.instruments (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(bar_id) REFERENCES public.market_bars (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(evidence_id) REFERENCES public.evidence_bundles (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(portfolio_id) REFERENCES public.portfolio_snapshots (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(position_id) REFERENCES public.positions (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_market_state_position_version FOREIGN KEY(position_id, position_ledger_version) REFERENCES public.position_versions (position_id, ledger_version) ON DELETE RESTRICT\n)\n\n', '\nCREATE TABLE public.decisions (\n\tid VARCHAR(255) NOT NULL, \n\tmarket_state_id VARCHAR(255) NOT NULL, \n\tchoice VARCHAR(255) NOT NULL, \n\tmodel_id VARCHAR(255), \n\tprompt_version VARCHAR(255) NOT NULL, \n\tquestion_version VARCHAR(255) NOT NULL, \n\tconfig_version VARCHAR(255) NOT NULL, \n\tinput_hash VARCHAR(255) NOT NULL, \n\tlatency_ms INTEGER NOT NULL, \n\tvalid_until TIMESTAMP WITH TIME ZONE NOT NULL, \n\ttrace_id VARCHAR(255) NOT NULL, \n\treason_code VARCHAR(255) NOT NULL, \n\tconfidence NUMERIC(38, 18), \n\tdistribution JSONB, \n\ttyped_answers JSONB, \n\tapi_units NUMERIC(38, 18), \n\testimated_cost NUMERIC(38, 18), \n\tregime VARCHAR(255), \n\tevidence_quality NUMERIC(38, 18), \n\tsignal_conflict NUMERIC(38, 18), \n\tshadow_choice VARCHAR(255), \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(market_state_id) REFERENCES public.market_states (id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_decision_market_state UNIQUE (id, market_state_id)\n)\n\n', '\nCREATE TABLE public.trade_proposals (\n\tid VARCHAR(255) NOT NULL, \n\tdecision_id VARCHAR(255) NOT NULL, \n\tmarket_state_id VARCHAR(255) NOT NULL, \n\tinstrument_id VARCHAR(255) NOT NULL, \n\ttarget VARCHAR(255) NOT NULL, \n\tquantity NUMERIC(38, 18) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tvalid_until TIMESTAMP WITH TIME ZONE NOT NULL, \n\ttrace_id VARCHAR(255) NOT NULL, \n\trationale_codes JSONB NOT NULL, \n\tlimit_price NUMERIC(38, 18), \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(decision_id) REFERENCES public.decisions (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(market_state_id) REFERENCES public.market_states (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(instrument_id) REFERENCES public.instruments (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_proposal_decision_market_state FOREIGN KEY(decision_id, market_state_id) REFERENCES public.decisions (id, market_state_id) ON DELETE RESTRICT\n)\n\n', '\nCREATE TABLE public.risk_decisions (\n\tid VARCHAR(255) NOT NULL, \n\tproposal_id VARCHAR(255) NOT NULL, \n\tapproved BOOLEAN NOT NULL, \n\treason_code VARCHAR(255) NOT NULL, \n\treason_codes JSONB NOT NULL, \n\tpolicy_version INTEGER NOT NULL, \n\texposure_snapshot JSONB NOT NULL, \n\tdecided_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tvalid_until TIMESTAMP WITH TIME ZONE NOT NULL, \n\ttrace_id VARCHAR(255) NOT NULL, \n\treservation_id VARCHAR(255), \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(proposal_id) REFERENCES public.trade_proposals (id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_risk_decision_proposal UNIQUE (id, proposal_id), \n\tCONSTRAINT fk_risk_decision_policy_version FOREIGN KEY(policy_version) REFERENCES public.risk_policies (version) ON DELETE RESTRICT\n)\n\n', '\nCREATE TABLE public.order_intents (\n\tid VARCHAR(255) NOT NULL, \n\tproposal_id VARCHAR(255) NOT NULL, \n\trisk_decision_id VARCHAR(255) NOT NULL, \n\tclient_order_id VARCHAR(255) NOT NULL, \n\tinstrument_id VARCHAR(255) NOT NULL, \n\tside VARCHAR(255) NOT NULL, \n\torder_type VARCHAR(255) NOT NULL, \n\tquantity NUMERIC(38, 18) NOT NULL, \n\tcapability_version INTEGER NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\ttrace_id VARCHAR(255) NOT NULL, \n\tlimit_price NUMERIC(38, 18), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_intent_proposal UNIQUE (proposal_id), \n\tCONSTRAINT uq_intent_client_order UNIQUE (client_order_id), \n\tCONSTRAINT uq_intent_client_pair UNIQUE (id, client_order_id), \n\tFOREIGN KEY(proposal_id) REFERENCES public.trade_proposals (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(risk_decision_id) REFERENCES public.risk_decisions (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(instrument_id) REFERENCES public.instruments (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_intent_decision_proposal FOREIGN KEY(risk_decision_id, proposal_id) REFERENCES public.risk_decisions (id, proposal_id) ON DELETE RESTRICT\n)\n\n', '\nCREATE TABLE public.risk_reservations (\n\tid VARCHAR(255) NOT NULL, \n\tproposal_id VARCHAR(255) NOT NULL, \n\trisk_decision_id VARCHAR(255) NOT NULL, \n\tcurrency VARCHAR(255) NOT NULL, \n\treserved_notional NUMERIC(38, 18) NOT NULL, \n\tstate VARCHAR(255) NOT NULL, \n\tversion INTEGER NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\ttrace_id VARCHAR(255) NOT NULL, \n\treleased_at TIMESTAMP WITH TIME ZONE, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_reservation_proposal UNIQUE (proposal_id), \n\tCONSTRAINT uq_reservation_decision UNIQUE (risk_decision_id), \n\tFOREIGN KEY(proposal_id) REFERENCES public.trade_proposals (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(risk_decision_id) REFERENCES public.risk_decisions (id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_reservation_decision_pair UNIQUE (id, risk_decision_id), \n\tCONSTRAINT fk_reservation_decision_proposal FOREIGN KEY(risk_decision_id, proposal_id) REFERENCES public.risk_decisions (id, proposal_id) ON DELETE RESTRICT\n)\n\n', '\nCREATE TABLE public.broker_orders (\n\tid VARCHAR(255) NOT NULL, \n\tintent_id VARCHAR(255) NOT NULL, \n\tclient_order_id VARCHAR(255) NOT NULL, \n\tbroker_order_id VARCHAR(255), \n\tstatus VARCHAR(255) NOT NULL, \n\trequested_quantity NUMERIC(38, 18) NOT NULL, \n\tfilled_quantity NUMERIC(38, 18) NOT NULL, \n\tversion INTEGER NOT NULL, \n\tupdated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\ttrace_id VARCHAR(255) NOT NULL, \n\tadapter VARCHAR(100) NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_order_intent UNIQUE (intent_id), \n\tCONSTRAINT uq_order_client UNIQUE (client_order_id), \n\tCONSTRAINT uq_order_broker UNIQUE (adapter, broker_order_id), \n\tCONSTRAINT ck_order_fill CHECK (filled_quantity <= requested_quantity), \n\tFOREIGN KEY(intent_id) REFERENCES public.order_intents (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_order_intent_client FOREIGN KEY(intent_id, client_order_id) REFERENCES public.order_intents (id, client_order_id) ON DELETE RESTRICT\n)\n\n', '\nCREATE TABLE public.execution_reports (\n\tid VARCHAR(255) NOT NULL, \n\torder_id VARCHAR(255) NOT NULL, \n\tstatus VARCHAR(255) NOT NULL, \n\trequested_quantity NUMERIC(38, 18) NOT NULL, \n\tfilled_quantity NUMERIC(38, 18) NOT NULL, \n\treconciliation VARCHAR(255) NOT NULL, \n\toccurred_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\treceived_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\ttrace_id VARCHAR(255) NOT NULL, \n\tbroker_event_id VARCHAR(255), \n\taverage_fill_price NUMERIC(38, 18), \n\tfee NUMERIC(38, 18), \n\treason_code VARCHAR(255), \n\tadapter VARCHAR(100) NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_report_broker_event UNIQUE (adapter, broker_event_id), \n\tCONSTRAINT ck_report_fill CHECK (filled_quantity <= requested_quantity), \n\tFOREIGN KEY(order_id) REFERENCES public.broker_orders (id) ON DELETE RESTRICT\n)\n\n', 'ALTER TABLE public.risk_decisions ADD CONSTRAINT fk_decision_reservation FOREIGN KEY(reservation_id, id) REFERENCES public.risk_reservations (id, risk_decision_id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED')

